func (q *Queries) PersonExists(ctx context.Context, arg PersonExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, personExists, arg.ID, arg.ViewerID)
	var found bool
	err := row.Scan(&found)
	return found, err
}

const resolveReport = `-- name: ResolveReport :execrows
update reports set status = 'resolved', resolved_by = $1, resolved_at = now() where id = $2 and status = 'open'
`

type ResolveReportParams struct {
	By uuid.NullUUID `json:"by"`
	ID uuid.UUID     `json:"id"`
}

func (q *Queries) ResolveReport(ctx context.Context, arg ResolveReportParams) (int64, error) {
	result, err := q.db.Exec(ctx, resolveReport, arg.By, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const searchPeople = `-- name: SearchPeople :many
select u.id, u.username::text as username, u.display_name, u.avatar_url,
       coalesce((select case when f.status = 'accepted' then 'friends'
                             when f.requester_id = $1 then 'request_sent'
                             else 'request_received' end
                   from friendships f
                  where (f.requester_id = $1 and f.addressee_id = u.id)
                     or (f.requester_id = u.id and f.addressee_id = $1)), 'none')::text as relationship
  from users u
 where u.deleted_at is null and u.id <> $1
   and not exists (select 1 from blocks b
                    where (b.blocker_id = $1 and b.blocked_id = u.id)
                       or (b.blocker_id = u.id and b.blocked_id = $1))
   and (position($2::text in lower(u.username::text)) > 0
        or position($2::text in lower(u.display_name)) > 0
        or similarity(lower(u.display_name), $2::text) > 0.35
        or similarity(lower(u.username::text), $2::text) > 0.35)
 order by (lower(u.username::text) = $2::text) desc,
          (lower(u.username::text) like $2::text || '%' or lower(u.display_name) like $2::text || '%') desc,
          greatest(similarity(lower(u.display_name), $2::text), similarity(lower(u.username::text), $2::text)) desc,
          u.display_name
 limit $3
`

type SearchPeopleParams struct {
	ViewerID uuid.UUID `json:"viewer_id"`
	Needle   string    `json:"needle"`
	MaxRows  int32     `json:"max_rows"`
}

type SearchPeopleRow struct {
	ID           uuid.UUID `json:"id"`
	Username     string    `json:"username"`
	DisplayName  string    `json:"display_name"`
	AvatarUrl    *string   `json:"avatar_url"`
	Relationship string    `json:"relationship"`
}

// People whose username or display name contains the text (or is close to it), never the caller and never anyone
// blocked either way. The relationship is from the caller's side.
func (q *Queries) SearchPeople(ctx context.Context, arg SearchPeopleParams) ([]SearchPeopleRow, error) {
	rows, err := q.db.Query(ctx, searchPeople, arg.ViewerID, arg.Needle, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPeopleRow
	for rows.Next() {
		var i SearchPeopleRow
		if err := rows.Scan(
			&i.ID,
			&i.Username,
			&i.DisplayName,
			&i.AvatarUrl,
			&i.Relationship,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

